package com.example.billing.domain;

import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import java.time.OffsetDateTime;
import org.hibernate.annotations.JavaType;
import org.hibernate.annotations.JdbcType;
import org.hibernate.annotations.JdbcTypeCode;
import org.hibernate.annotations.TimeZoneColumn;
import org.hibernate.annotations.TimeZoneStorage;
import org.hibernate.annotations.TimeZoneStorageType;
import org.hibernate.annotations.Type;
import org.hibernate.type.SqlTypes;

@Entity
public class Gadget {
    @Id Long id;
    @JdbcTypeCode(SqlTypes.JSON) String a;
    @Type(PointType.class) String b;
    @JavaType(PointJavaType.class) String c;
    @JdbcType(PointJdbcType.class) String d;
    @TimeZoneStorage(TimeZoneStorageType.NORMALIZE) OffsetDateTime e;
    @TimeZoneColumn(name = "f_tz") OffsetDateTime f;
}

package com.example.billing.domain;

import org.hibernate.annotations.JavaTypeRegistration;
import org.hibernate.annotations.JdbcTypeRegistration;

@JdbcTypeRegistration(PointJdbcType.class)
@JavaTypeRegistration(javaType = Point.class, descriptorClass = PointJavaType.class)
class TypeRegistrations {
}
